    for _, sidecar := range sidecars {
        for i := range sidecar.Column {
            commitments = append(commitments, kzg.Bytes48(sidecar.KzgCommitments[i])) // raw byte cast
            proofs = append(proofs, kzg.Bytes48(sidecar.KzgProofs[i]))                 // raw byte cast
        }
    }
    verified, err := kzg.VerifyCellKZGProofBatch(commitments, indices, cells, proofs)
    // ...
}

