// Subgroup check implementation chain:
// Prysm Go (kzg.go:105) -> ckzg4844.VerifyCellKZGProofBatch (CGo) ->
// c-kzg-4844 eip7594.c -> validate_kzg_g1 (bytes.c:81-95) -> blst_p1_in_g1 (blst v0.3.14)
func VerifyCellKZGProofBatch(commitmentsBytes []Bytes48, cellIndices []uint64, cells []Cell, proofsBytes []Bytes48) (bool, error) {
    ckzgCells := make([]ckzg4844.Cell, len(cells))
    for i := range cells { ckzgCells[i] = ckzg4844.Cell(cells[i]) }
    return ckzg4844.VerifyCellKZGProofBatch(commitmentsBytes, cellIndices, ckzgCells, proofsBytes)
}

// Go layer: NO commitment deduplication in VerifyDataColumnsSidecarKZGProofs
// One commitment entry per (sidecar, column) pair passed directly to C library.
// C library (c-kzg-4844 eip7594.c:316-374) performs deduplication using byte-level memcmp:
// deduplicate_commitments(unique_commitments, commitment_indices, commitment_count, commitments_bytes, n)
// After deduplication: compute_r_powers_for_verify_cell_kzg_proof_batch hashes unique_commitments
// AND commitment_indices into the Fiat-Shamir challenge, binding cell-to-commitment mapping.
for _, sidecar := range sidecars {
    for i := range sidecar.Column {
        commitments = append(commitments, kzg.Bytes48(sidecar.KzgCommitments[i]))
        indices = append(indices, sidecar.Index)
        cells = append(cells, kzg.Cell(sidecar.Column[i]))
        proofs = append(proofs, kzg.Bytes48(sidecar.KzgProofs[i]))
    }
}
